def build_mcq_prompt(topic,results,count,difficulty,previous):
    ctx="\n\n".join(f"SOURCE CHUNK ID: {r.chunk.chunk_id}\nFILE: {r.chunk.filename}\nPAGE: {r.chunk.page_number if r.chunk.page_number is not None else 'Not available'}\nTEXT:\n{r.chunk.text}" for r in results)
    return f"""You are an expert MDCAT question writer. Topic: {topic}. Difficulty: {difficulty}. Generate exactly {count} MCQs. Use ONLY the supplied context; never use outside knowledge or invent facts. Each question must be self-contained, have exactly four plausible options A-D, exactly one correct answer, a concise source-grounded explanation, and source_chunk_ids. Avoid duplicates. Return JSON only in this format: {{"questions":[{{"question":"...","options":{{"A":"...","B":"...","C":"...","D":"..."}},"correct_answer":"A","explanation":"...","source_chunk_ids":["chunk"]}}]}}. Previous questions to avoid: {previous[-30:]}. CONTEXT:\n{ctx}"""
